          <div class="overlay-actions" role="group" aria-label="存档与脱困">
            <button class="overlay-action" type="button" data-action="unstuck" aria-label="脱困：回到最近的安全点" title="脱困：回到最近的安全点">脱困</button>
            <button class="overlay-action" type="button" data-action="export" aria-label="导出存档" title="导出存档">导出存档</button>
            <button class="overlay-action" type="button" data-action="import" aria-label="导入存档" title="导入存档">导入存档</button>
            <button class="overlay-action" type="button" data-action="cloud" aria-label="云同步" title="登录后可在多设备间同步存档与 AI 会话">云同步</button>
          </div>
